function validate([cars]) {
  if (cars.length < 1 || cars.length > 100000) return 'cars needs 1 to 10^5 cars.';
  for (let i = 0; i < cars.length; i++) {
    const car = cars[i];
    if (!Array.isArray(car) || car.length !== 2) return 'Each car is a [position, speed] pair.';
    if (car.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Positions and speeds are integers from 1 to 10^6.';
    if (i > 0 && cars[i - 1][0] >= car[0]) return 'Positions must strictly increase.';
  }
  return null;
}

