function getCollisionTimes(cars) {
  const n = cars.length;
  const answer = new Array(n).fill(-1);
  const stack = [];

  for (let i = n - 1; i >= 0; i--) {
    const [position, speed] = cars[i];
    while (stack.length > 0) {
      const ahead = stack[stack.length - 1];
      const [aheadPosition, aheadSpeed] = cars[ahead];
      if (speed <= aheadSpeed) {
        stack.pop();
        continue;
      }
      const time = (aheadPosition - position) / (speed - aheadSpeed);
      if (answer[ahead] !== -1 && time > answer[ahead]) {
        stack.pop();
        continue;
      }
      answer[i] = time;
      break;
    }
    stack.push(i);
  }
  return answer;
}

