function getCollisionTimes(cars) {
  // Event simulation: fleets of consecutive cars, advanced from one collision to the next.
  const answer = cars.map(() => -1);
  let fleets = cars.map(([position, speed], index) => ({ first: index, last: index, position, speed }));
  let now = 0;
  for (;;) {
    let soonest = Infinity;
    for (let k = 0; k + 1 < fleets.length; k++) {
      const back = fleets[k], front = fleets[k + 1];
      if (back.speed > front.speed) soonest = Math.min(soonest, (front.position - back.position) / (back.speed - front.speed));
    }
    if (soonest === Infinity) return answer;
    const meets = [];
    for (let k = 0; k + 1 < fleets.length; k++) {
      const back = fleets[k], front = fleets[k + 1];
      meets.push(back.speed > front.speed && (front.position - back.position) / (back.speed - front.speed) <= soonest + 1e-9);
    }
    now += soonest;
    for (const fleet of fleets) fleet.position += fleet.speed * soonest;
    const merged = [fleets[0]];
    for (let k = 1; k < fleets.length; k++) {
      if (meets[k - 1]) {
        const back = merged[merged.length - 1];
        answer[back.last] = now;
        back.last = fleets[k].last;
        back.position = fleets[k].position;
        back.speed = Math.min(back.speed, fleets[k].speed);
      } else merged.push(fleets[k]);
    }
    fleets = merged;
  }
}

