function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const maxGap = size === 'large' ? 400 : 1 + Math.floor(rand() * 5);
  const maxSpeed = size === 'large' ? (rand() < 0.5 ? 1000000 : 50) : 1 + Math.floor(rand() * 8);
  const cars = [];
  let position = 1 + Math.floor(rand() * maxGap);
  for (let i = 0; i < n; i++) {
    cars.push([position, 1 + Math.floor(rand() * maxSpeed)]);
    position += 1 + Math.floor(rand() * maxGap);
  }
  return [cars];
}
